//! The RPC specification: what `#[api]` registers, and how it is exported.
//!
//! Every function annotated with [`api`](crate::api) registers an
//! [`ApiFnDescriptor`] in a process-wide registry when the crate is compiled
//! for the server (the `ssr` feature). [`collect`] walks that registry and
//! produces an [`ApiSpec`]: routes, HTTP encodings, docs, and a JSON Schema
//! for every argument and return value, generated by [`schemars`] so `serde`
//! attributes are honored exactly. The spec leaves the server in one of two
//! ways:
//!
//! - [`export_if_requested`], called first thing in `main`, writes the spec to
//!   the file named by the `LEPTOSKIT_RPC_SPEC_OUT` environment variable and
//!   exits. This is how `leptoskit rpc spec` and `leptoskit rpc generate`
//!   extract it: they build the server binary and run it with that variable
//!   set, so the spec always matches the code that was just compiled;
//! - [`openapi_router`] (feature `axum`) serves the public functions as an
//!   OpenAPI 3.1 document for Swagger UI, Redoc, or any OpenAPI toolchain.
//!
//! ```no_run
//! # #[cfg(feature = "ssr")]
//! fn main() {
//! 	leptoskit_rpc::spec::export_if_requested();
//! 	// ...start the server as usual
//! }
//! # #[cfg(not(feature = "ssr"))]
//! # fn main() {}
//! ```

use std::collections::BTreeMap;
use std::collections::HashMap;
use std::path::Path;
use std::path::PathBuf;

use leptos::server_fn::ContentType;
use leptos::server_fn::Http;
use leptos::server_fn::ServerFn;
use leptos::server_fn::codec::Encoding;
use leptos::server_fn::error::FromServerFnError;
pub use leptoskit_rpc_codegen::ApiFunction;
pub use leptoskit_rpc_codegen::ApiParam;
pub use leptoskit_rpc_codegen::ApiSpec;
pub use leptoskit_rpc_codegen::HttpInput;
pub use leptoskit_rpc_codegen::HttpOutput;
pub use leptoskit_rpc_codegen::spec::SPEC_DESCRIPTION_ENV;
pub use leptoskit_rpc_codegen::spec::SPEC_OUT_ENV;
pub use leptoskit_rpc_codegen::spec::SPEC_SERVERS_ENV;
pub use leptoskit_rpc_codegen::spec::SPEC_TITLE_ENV;
use leptoskit_rpc_codegen::spec::SPEC_VERSION;
pub use leptoskit_rpc_codegen::spec::SPEC_VERSION_ENV;
pub use schemars;
use schemars::Schema;
use schemars::SchemaGenerator;
use schemars::generate::SchemaSettings;

/// One `#[api]` function, as the macro registers it.
///
/// Every field is a compile-time constant or a function pointer so the
/// descriptor can live in a `static`; schemas are produced lazily, through a
/// shared [`SchemaGenerator`], when [`collect`] runs.
#[derive(Debug)]
pub struct ApiFnDescriptor {
	/// The operation name; the function name unless `#[api(name = "...")]`.
	pub name: &'static str,
	/// `module_path!()` at the definition.
	pub module_path: &'static str,
	/// The struct `#[server]` generated for the function.
	pub struct_name: &'static str,
	/// The doc comment, `///` markers stripped.
	pub docs: &'static str,
	/// The route, from `ServerFn::PATH`.
	pub path: &'static str,
	/// The HTTP method of the input encoding.
	pub method: http::Method,
	/// The request content type.
	pub input_content_type: &'static str,
	/// The success response content type.
	pub output_content_type: &'static str,
	/// The error response content type.
	pub error_content_type: &'static str,
	/// The arguments, in declaration order.
	pub params: &'static [ApiParamDescriptor],
	/// Produces the schema of the success value.
	pub output_schema: fn(&mut SchemaGenerator) -> Schema,
	/// `#[api(internal)]`.
	pub internal: bool,
	/// Whether the function carries `#[deprecated]`.
	pub deprecated: bool,
	/// `#[api(tag = "...")]`, in order.
	pub tags: &'static [&'static str],
}

/// One argument of an [`ApiFnDescriptor`].
#[derive(Debug)]
pub struct ApiParamDescriptor {
	/// The argument name, as it appears on the wire.
	pub name: &'static str,
	/// The argument's doc, from the `# Arguments` section of the function's
	/// doc comment.
	pub docs: &'static str,
	/// Produces the schema of the argument type.
	pub schema: fn(&mut SchemaGenerator) -> Schema,
	/// Whether the argument must be sent; `false` for `#[server(default)]`.
	pub required: bool,
}

inventory::collect!(ApiFnDescriptor);

/// What the HTTP protocol of a server function looks like on the wire.
///
/// Implemented for every `Http<Input, Output>` protocol; the websocket and
/// streaming protocols have no implementation, which is what makes `#[api]`
/// reject them at compile time.
pub trait HttpProtocolInfo {
	/// The request method.
	const METHOD: http::Method;
	/// The request content type.
	const INPUT_CONTENT_TYPE: &'static str;
	/// The success response content type.
	const OUTPUT_CONTENT_TYPE: &'static str;
}

impl<Input: Encoding, Output: Encoding> HttpProtocolInfo for Http<Input, Output> {
	const INPUT_CONTENT_TYPE: &'static str = Input::CONTENT_TYPE;
	const METHOD: http::Method = Input::METHOD;
	const OUTPUT_CONTENT_TYPE: &'static str = Output::CONTENT_TYPE;
}

/// The HTTP method a server function's requests use.
pub const fn method_of<T: ServerFn>() -> http::Method
where
	T::Protocol: HttpProtocolInfo,
{
	<T::Protocol as HttpProtocolInfo>::METHOD
}

/// The request content type of a server function.
pub const fn input_content_type_of<T: ServerFn>() -> &'static str
where
	T::Protocol: HttpProtocolInfo,
{
	<T::Protocol as HttpProtocolInfo>::INPUT_CONTENT_TYPE
}

/// The success response content type of a server function.
pub const fn output_content_type_of<T: ServerFn>() -> &'static str
where
	T::Protocol: HttpProtocolInfo,
{
	<T::Protocol as HttpProtocolInfo>::OUTPUT_CONTENT_TYPE
}

/// The error response content type of a server function.
pub const fn error_content_type_of<T: ServerFn>() -> &'static str {
	<<T::Error as FromServerFnError>::Encoder as ContentType>::CONTENT_TYPE
}

/// The metadata an exported spec carries.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SpecOptions {
	/// The RPC title.
	pub title: String,
	/// The RPC version.
	pub version: String,
	/// A longer description.
	pub description: Option<String>,
	/// The base URLs the RPC is served from.
	pub servers: Vec<String>,
}

impl SpecOptions {
	/// Options with a title and version.
	pub fn new(title: impl Into<String>, version: impl Into<String>) -> Self {
		Self {
			title: title.into(),
			version: version.into(),
			description: None,
			servers: Vec::new(),
		}
	}

	/// Options from the `LEPTOSKIT_RPC_SPEC_*` environment variables the CLI
	/// sets, falling back to a generic title and version `0.0.0`.
	#[must_use]
	pub fn from_env() -> Self {
		Self::from_lookup(|name| std::env::var(name).ok())
	}

	/// [`SpecOptions::from_env`] over any variable source; empty values count
	/// as unset.
	pub fn from_lookup(lookup: impl Fn(&str) -> Option<String>) -> Self {
		let read = |name: &str| lookup(name).filter(|value| !value.is_empty());
		Self {
			title: read(SPEC_TITLE_ENV).unwrap_or_else(|| "RPC".to_owned()),
			version: read(SPEC_VERSION_ENV).unwrap_or_else(|| "0.0.0".to_owned()),
			description: read(SPEC_DESCRIPTION_ENV),
			servers: read(SPEC_SERVERS_ENV)
				.map(|servers| {
					servers
						.split(',')
						.map(str::trim)
						.filter(|server| !server.is_empty())
						.map(ToOwned::to_owned)
						.collect()
				})
				.unwrap_or_default(),
		}
	}

	/// Sets the description.
	#[must_use]
	pub fn with_description(mut self, description: impl Into<String>) -> Self {
		self.description = Some(description.into());
		self
	}

	/// Adds a server URL.
	#[must_use]
	pub fn with_server(mut self, url: impl Into<String>) -> Self {
		self.servers.push(url.into());
		self
	}
}

/// Every registered descriptor, sorted by name then module path.
pub fn descriptors() -> Vec<&'static ApiFnDescriptor> {
	let mut descriptors: Vec<&'static ApiFnDescriptor> =
		inventory::iter::<ApiFnDescriptor>().collect();
	descriptors.sort_by(|a, b| {
		a.name
			.cmp(b.name)
			.then_with(|| a.module_path.cmp(b.module_path))
	});
	descriptors
}

/// Builds the spec from every registered `#[api]` function, internal ones
/// included; filter with [`ApiSpec::public`] for publication.
///
/// # Errors
///
/// Returns [`SpecError::DuplicateName`] when two functions share a name and
/// [`SpecError::DuplicateRoute`] when two share a route and method: generated
/// clients could not tell them apart, and the server would silently route one
/// of them to the other's handler.
pub fn collect(options: &SpecOptions) -> Result<ApiSpec, SpecError> {
	collect_from(&descriptors(), options)
}

/// [`collect`] over an explicit set of descriptors, in the order given.
///
/// # Errors
///
/// As [`collect`].
pub fn collect_from(
	descriptors: &[&ApiFnDescriptor],
	options: &SpecOptions,
) -> Result<ApiSpec, SpecError> {
	let mut by_name: HashMap<&str, &ApiFnDescriptor> = HashMap::new();
	let mut by_route: HashMap<(&str, &str), &ApiFnDescriptor> = HashMap::new();
	for descriptor in descriptors.iter().copied() {
		if let Some(existing) = by_name.insert(descriptor.name, descriptor) {
			return Err(SpecError::DuplicateName {
				name: descriptor.name.to_owned(),
				first: existing.module_path.to_owned(),
				second: descriptor.module_path.to_owned(),
			});
		}
		let route = (descriptor.path, descriptor.method.as_str());
		if let Some(existing) = by_route.insert(route, descriptor) {
			return Err(SpecError::DuplicateRoute {
				method: descriptor.method.to_string(),
				path: descriptor.path.to_owned(),
				first: existing.name.to_owned(),
				second: descriptor.name.to_owned(),
			});
		}
	}

	let mut generator = SchemaSettings::draft2020_12()
		.with(|settings| {
			settings.definitions_path = "/components/schemas".into();
			settings.meta_schema = None;
		})
		.into_generator();
	let functions = descriptors
		.iter()
		.map(|descriptor| {
			let params = descriptor
				.params
				.iter()
				.map(|param| {
					ApiParam {
						name: param.name.to_owned(),
						docs: param.docs.to_owned(),
						schema: (param.schema)(&mut generator).to_value(),
						required: param.required,
					}
				})
				.collect();
			let output_schema = (descriptor.output_schema)(&mut generator).to_value();
			ApiFunction {
				name: descriptor.name.to_owned(),
				module_path: descriptor.module_path.to_owned(),
				struct_name: descriptor.struct_name.to_owned(),
				docs: descriptor.docs.to_owned(),
				path: descriptor.path.to_owned(),
				method: descriptor.method.to_string(),
				input: classify_input(&descriptor.method, descriptor.input_content_type),
				output: classify_output(descriptor.output_content_type),
				error_content_type: descriptor.error_content_type.to_owned(),
				params,
				output_schema,
				internal: descriptor.internal,
				deprecated: descriptor.deprecated,
				tags: descriptor
					.tags
					.iter()
					.map(|tag| (*tag).to_owned())
					.collect(),
			}
		})
		.collect();
	let schemas: BTreeMap<String, serde_json::Value> =
		generator.take_definitions(false).into_iter().collect();

	Ok(ApiSpec {
		leptoskit_rpc_spec: SPEC_VERSION,
		title: options.title.clone(),
		version: options.version.clone(),
		description: options.description.clone(),
		servers: options.servers.clone(),
		functions,
		schemas: schemas.into_iter().collect(),
	})
}

/// Maps a request method and content type to the encoding a client must use.
fn classify_input(method: &http::Method, content_type: &str) -> HttpInput {
	match content_type {
		"application/x-www-form-urlencoded" if *method == http::Method::GET => HttpInput::Query,
		"application/x-www-form-urlencoded" => HttpInput::Form,
		"application/json" => HttpInput::Json,
		other => {
			HttpInput::Other {
				content_type: other.to_owned(),
			}
		}
	}
}

/// Maps a response content type to the decoding a client must use.
fn classify_output(content_type: &str) -> HttpOutput {
	match content_type {
		"application/json" => HttpOutput::Json,
		other => {
			HttpOutput::Other {
				content_type: other.to_owned(),
			}
		}
	}
}

/// Writes the spec as JSON to `path`, creating parent directories.
///
/// # Errors
///
/// Returns an error when collection fails or the file cannot be written.
pub fn write_to(options: &SpecOptions, path: &Path) -> Result<ApiSpec, SpecError> {
	let spec = collect(options)?;
	let json = spec.to_json().map_err(SpecError::Codegen)?;
	if let Some(parent) = path.parent() {
		if !parent.as_os_str().is_empty() {
			std::fs::create_dir_all(parent).map_err(|source| {
				SpecError::Write {
					path: parent.to_path_buf(),
					source,
				}
			})?;
		}
	}
	std::fs::write(path, json).map_err(|source| {
		SpecError::Write {
			path: path.to_path_buf(),
			source,
		}
	})?;
	Ok(spec)
}

/// Writes the spec when the CLI asks for it, then exits the process.
///
/// Call this first in `main`, before anything that binds ports or opens
/// databases. When `LEPTOSKIT_RPC_SPEC_OUT` is unset it returns immediately
/// and the server starts as usual. When it is set — `leptoskit rpc spec` and
/// `leptoskit rpc generate` set it — the spec is written there and the
/// process exits with status `0`, or `1` with the error on stderr.
///
/// Title, version, description, and servers come from the
/// `LEPTOSKIT_RPC_SPEC_*` variables the CLI sets from `leptoskit.toml`; use
/// [`export_if_requested_with`] to supply them from code instead.
pub fn export_if_requested() {
	export_if_requested_with(&SpecOptions::from_env());
}

/// [`export_if_requested`] with explicit metadata.
pub fn export_if_requested_with(options: &SpecOptions) {
	if let Some(outcome) = maybe_export_from(|name| std::env::var(name).ok(), options) {
		match outcome {
			Ok(path) => {
				eprintln!("wrote the RPC specification to {}", path.display());
				std::process::exit(0);
			}
			Err(error) => {
				eprintln!("error: could not export the RPC specification: {error}");
				std::process::exit(1);
			}
		}
	}
}

/// Writes the spec when `LEPTOSKIT_RPC_SPEC_OUT` is set, without exiting.
///
/// Returns `None` when no export was requested, so callers can decide what
/// to do next.
pub fn maybe_export(options: &SpecOptions) -> Option<Result<PathBuf, SpecError>> {
	maybe_export_from(|name| std::env::var(name).ok(), options)
}

/// [`maybe_export`] over any variable source.
pub fn maybe_export_from(
	lookup: impl Fn(&str) -> Option<String>,
	options: &SpecOptions,
) -> Option<Result<PathBuf, SpecError>> {
	let path = PathBuf::from(lookup(SPEC_OUT_ENV).filter(|path| !path.is_empty())?);
	Some(write_to(options, &path).map(|_| path))
}

/// Serves the spec as OpenAPI: `GET /openapi.json` and `GET /openapi.yaml`,
/// relative to wherever the router is nested.
///
/// The spec is collected once, when the router is built, with internal
/// functions left out: this is the publicized document.
///
/// # Errors
///
/// Returns an error when collection fails; see [`collect`].
#[cfg(feature = "axum")]
pub fn openapi_router(options: &SpecOptions) -> Result<axum::Router, SpecError> {
	use axum::http::HeaderValue;
	use axum::http::header;
	use axum::response::IntoResponse;
	use axum::routing::get;

	let spec = collect(options)?.public();
	let json = serde_json::to_string_pretty(&spec.to_openapi()).map_err(|source| {
		SpecError::Codegen(leptoskit_rpc_codegen::CodegenError::Serialize(source))
	})?;
	let yaml = spec.to_openapi_yaml();
	let json_response = move || {
		let json = json.clone();
		async move {
			(
				[(
					header::CONTENT_TYPE,
					HeaderValue::from_static("application/json"),
				)],
				json,
			)
				.into_response()
		}
	};
	let yaml_response = move || {
		let yaml = yaml.clone();
		async move {
			(
				[(
					header::CONTENT_TYPE,
					HeaderValue::from_static("application/yaml"),
				)],
				yaml,
			)
				.into_response()
		}
	};
	Ok(axum::Router::new()
		.route("/openapi.json", get(json_response))
		.route("/openapi.yaml", get(yaml_response)))
}

/// Failures while building or exporting the spec.
#[derive(Debug, thiserror::Error)]
pub enum SpecError {
	/// Two `#[api]` functions share a name.
	#[error(
		"two #[api] functions are named `{name}` (in `{first}` and `{second}`); rename one, or \
		 give it `#[api(name = \"...\")]`"
	)]
	DuplicateName {
		/// The shared name.
		name: String,
		/// Where the first lives.
		first: String,
		/// Where the second lives.
		second: String,
	},
	/// Two `#[api]` functions share a route.
	#[error(
		"`{first}` and `{second}` both answer `{method} {path}`; give one of them a different \
		 `endpoint` or `prefix` in its #[server] attribute"
	)]
	DuplicateRoute {
		/// The HTTP method.
		method: String,
		/// The shared route.
		path: String,
		/// The first function.
		first: String,
		/// The second function.
		second: String,
	},
	/// The spec could not be serialized.
	#[error(transparent)]
	Codegen(leptoskit_rpc_codegen::CodegenError),
	/// The spec file could not be written.
	#[error("could not write {path}")]
	Write {
		/// The path that failed.
		path: PathBuf,
		/// The underlying error.
		source: std::io::Error,
	},
}
